-- READ-ONLY state check for 20261027040000_clients_merge (prod etbesmtdsjlmadaexvrv). One SELECT, one row. Changes nothing.
-- Counts that need a table/column that may not exist yet run through query_to_xml only when it exists (else NULL).
WITH o AS (SELECT to_regclass('public.clients') AS t, to_regclass('public.invoices') AS inv,
  EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='invoices' AND column_name='client_id') AS inv_cid),
q AS (SELECT o.*, (CASE WHEN o.t IS NOT NULL THEN 1 END) AS has_t FROM o)
SELECT
  q.t IS NOT NULL AS clients_table,
  (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name = ANY (ARRAY[
     'id','business_name','contact_name','email','phone','services','hourly_rate','notes','stripe_customer_id','user_id','portal_client_id',
     'invited_at','last_invite_at','invite_sent_count','archived_at','migrated_from','created_at','updated_at'])) AS clients_columns_of_18,
  (SELECT string_agg(c, ',') FROM unnest(ARRAY['id','business_name','contact_name','email','phone','services','hourly_rate','notes','stripe_customer_id',
     'user_id','portal_client_id','invited_at','last_invite_at','invite_sent_count','archived_at','migrated_from','created_at','updated_at']) c
   WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name=c)) AS clients_missing_columns,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND contype='p') AS clients_pkey,
  EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='business_name' AND is_nullable='NO') AS business_name_not_null,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND conname='clients_business_name_check') AS chk_business_name,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND conname='clients_email_check') AS chk_email,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND conname='clients_services_check') AS chk_services,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND contype='c' AND pg_get_constraintdef(oid) LIKE '%hourly_rate >=%') AS chk_hourly_rate,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.t AND contype='f' AND confrelid = 'public.users'::regclass) AS fk_clients_user_id,
  to_regclass('public.clients_email_key') IS NOT NULL AS idx_email,
  to_regclass('public.clients_user_id_key') IS NOT NULL AS idx_user_id,
  to_regclass('public.clients_portal_client_id_key') IS NOT NULL AS idx_portal_client_id,
  to_regclass('public.clients_stripe_customer_id_key') IS NOT NULL AS idx_stripe_customer_id,
  to_regclass('public.clients_active_idx') IS NOT NULL AS idx_active,
  coalesce((SELECT relrowsecurity FROM pg_class WHERE oid = q.t), false) AS rls_enabled,
  (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND tablename='clients') AS rls_policies,
  CASE WHEN q.t IS NOT NULL THEN has_table_privilege('service_role', 'public.clients', 'SELECT,INSERT,UPDATE,DELETE') END AS service_role_grant,
  CASE WHEN q.t IS NOT NULL THEN has_table_privilege('anon', 'public.clients', 'SELECT') OR has_table_privilege('authenticated', 'public.clients', 'SELECT') END AS anon_or_auth_can_select,
  q.inv_cid AS invoices_client_id,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.inv AND contype='f' AND confrelid = q.t) AS fk_invoices_client_id,
  to_regclass('public.invoices_client_id_idx') IS NOT NULL AS idx_invoices_client_id,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.inv AND conname='invoices_client_check') AS chk_invoices_client,
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = q.inv AND conname='invoices_recipient_check') AS old_recipient_check_still_there,
  to_regprocedure('public.invoices_legacy_recipient_readonly()') IS NOT NULL AS readonly_function,
  EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = q.inv AND tgname='invoices_legacy_recipient_readonly' AND NOT tgisinternal) AS readonly_trigger,
  obj_description(q.t, 'pg_class') IS NOT NULL AS clients_comment,
  (SELECT count(*) FROM public.invoices) AS invoices_total,
  CASE WHEN q.inv_cid THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.invoices WHERE client_id IS NULL', false, true, '')))[1]::text::int END AS invoices_null_client_id,
  CASE WHEN q.inv_cid THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.invoices WHERE client_id IS NULL AND (user_id IS NOT NULL OR ai_client_id IS NOT NULL)', false, true, '')))[1]::text::int END AS invoices_unresolved,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients', false, true, '')))[1]::text::int END AS clients_rows,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients WHERE user_id IS NOT NULL', false, true, '')))[1]::text::int END AS clients_with_user_id,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients WHERE portal_client_id IS NOT NULL', false, true, '')))[1]::text::int END AS clients_with_portal_client_id,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients c WHERE portal_client_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM portal.clients p WHERE p.id = c.portal_client_id)', false, true, '')))[1]::text::int END AS clients_portal_link_broken,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients c WHERE user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = c.user_id)', false, true, '')))[1]::text::int END AS clients_user_link_broken,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM (SELECT 1 FROM public.clients WHERE email IS NOT NULL GROUP BY email HAVING count(*) > 1) d', false, true, '')))[1]::text::int END AS clients_duplicate_emails,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM (SELECT 1 FROM public.clients WHERE user_id IS NOT NULL GROUP BY user_id HAVING count(*) > 1) d', false, true, '')))[1]::text::int END AS clients_duplicate_user_ids,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM (SELECT 1 FROM public.clients WHERE portal_client_id IS NOT NULL GROUP BY portal_client_id HAVING count(*) > 1) d', false, true, '')))[1]::text::int END AS clients_duplicate_portal_ids,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients WHERE email IS NULL AND user_id IS NULL AND portal_client_id IS NOT NULL', false, true, '')))[1]::text::int END AS ai_clients_without_email,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.clients WHERE migrated_from IS NULL', false, true, '')))[1]::text::int END AS clients_without_migrated_from,
  (SELECT count(*) FROM public.users u WHERE u.role IN ('client','user') AND lower(u.email) NOT LIKE '%@sleepysquid.com') AS source_client_users,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml($s$SELECT count(*) AS n FROM public.users u WHERE u.role IN ('client','user') AND lower(u.email) NOT LIKE '%@sleepysquid.com' AND NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.user_id = u.id)$s$, false, true, '')))[1]::text::int END AS client_users_not_migrated,
  (SELECT count(*) FROM portal.clients p WHERE NOT coalesce(p.is_example, false)) AS source_ai_clients,
  CASE WHEN q.t IS NOT NULL THEN (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM portal.clients p WHERE NOT coalesce(p.is_example, false) AND NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.portal_client_id = p.id)', false, true, '')))[1]::text::int END AS ai_clients_not_migrated
FROM q;
